import assert from 'node:assert/strict';import vm from 'node:vm';import {pathToFileURL} from 'node:url';
const api=(await import(pathToFileURL(process.argv[2]).href)).instantiateMithrilNative({});let count=0;const pass=()=>count++;
for(const args of [[],[undefined],[1,undefined],[1,2,3,4,5]])assert.equal(api.count(...args),args.length);assert.equal(api.count.length,2);assert.equal(api.count.name,'count');pass();
const getter=api.capture(1,2,3);assert.equal(getter(),3);assert.equal(getter(1,2,3,4,5),3);assert.equal(getter.name,'');assert.equal(getter.length,0);assert.throws(()=>Reflect.construct(getter,[]),TypeError);pass();
const inner=api.nested(1,2,3);assert.equal(inner.name,'inner');assert.equal(inner.length,1);assert.equal(Object.hasOwn(inner,'prototype'),true);assert.equal(inner()(),0);assert.equal(inner(1,2)(),2);assert.equal(inner(1,2)(1,2,3),2);pass();
assert.equal(api.defaultCapture.length,0);assert.equal(api.defaultCapture()(),0);assert.equal(api.defaultCapture(undefined,1)(),2);const opaque=()=>0;assert.equal(api.defaultCapture(opaque),opaque);pass();
assert.equal(api.moduleCount(),2);assert.equal(api.literalSubtract(),4);pass();
const values=[undefined,null,false,true,0,-0,1,-3,NaN,Infinity,'x','2',1n,-2n];for(const a of values)for(const b of values){for(const [name,op] of [['add',(a,b)=>a+b],['subtract',(a,b)=>a-b],['remainder',(a,b)=>a%b],['less',(a,b)=>a<b]]){let expected,failed=false;try{expected=op(a,b)}catch(e){failed=true;assert.throws(()=>api[name](a,b),e.constructor)}if(!failed)assert.ok(Object.is(api[name](a,b),expected));}}pass();
assert.ok(Object.is(api.subtract(-0,0),-0));assert.ok(Object.is(api.remainder(-0,3),-0));assert.equal(api.remainder(-5n,2n),-1n);assert.equal(api.less('10','2'),true);pass();
let events=[];const left={[Symbol.toPrimitive](hint){events.push('left:'+hint);return 4}},right={[Symbol.toPrimitive](hint){events.push('right:'+hint);return 2}};for(const name of ['add','subtract','remainder','less']){events=[];api[name](left,right);assert.deepEqual(events,['left:'+(name==='add'?'default':'number'),'right:'+(name==='add'?'default':'number')]);}pass();
const boom={};for(const name of ['add','subtract','remainder','less'])assert.throws(()=>api[name]({[Symbol.toPrimitive](){throw boom}},1),e=>e===boom);for(const name of ['add','subtract','remainder','less'])assert.throws(()=>api[name](Symbol('x'),1),TypeError);pass();
assert.throws(()=>api.remainder(1n,0n),RangeError);assert.equal(api.add('x',1),'x1');assert.equal(api.add(1,'x'),'1x');pass();
class C{}const object=new C();assert.equal(api.instance(object,C),true);assert.equal(api.instance({},C),false);assert.equal(api.instance(0,C),false);assert.equal(api.instance([],Array),true);pass();
let calls=0;const custom={[Symbol.hasInstance](v){assert.equal(this,custom);assert.equal(v,object);calls++;return 'raw truthy'}};assert.equal(api.instance(object,custom),true);assert.equal(calls,1);pass();
const stop={[Symbol.hasInstance](){throw boom}};assert.throws(()=>api.instance(object,stop),e=>e===boom);assert.throws(()=>api.instance(object,{[Symbol.hasInstance]:0}),TypeError);pass();
for(const ctor of [null,undefined,0,'x',{},()=>{}])assert.throws(()=>api.instance(object,ctor),TypeError);pass();
const foreign=vm.runInNewContext('(class C{})'),foreignObject=new foreign();assert.equal(api.instance(foreignObject,foreign),true);assert.equal(api.instance(foreignObject,C),false);pass();
const p=new Proxy(C,{get(t,k,r){if(k===Symbol.hasInstance)throw boom;return Reflect.get(t,k,r)}});assert.throws(()=>api.instance(object,p),e=>e===boom);const revoked=Proxy.revocable(C,{});revoked.revoke();assert.throws(()=>api.instance(object,revoked.proxy),TypeError);pass();
assert.equal(count,16);console.log('Native type prerequisites: 16 runtime contract groups passed.');
